use gpui::prelude::*;
use kui::components::dock::{Dock, DockIcon, DockItem, DockSelected};

let items = vec![
    DockItem::new("move", "Move", DockIcon::Pointer).with_shortcut("V"),
    DockItem::new("shapes", "Shapes", DockIcon::Rectangle).with_items(vec![
        DockItem::new("rectangle", "Rectangle", DockIcon::Rectangle).with_shortcut("R"),
        DockItem::new("ellipse", "Ellipse", DockIcon::Ellipse).with_shortcut("O"),
    ]),
];
let control = cx.new(|cx| Dock::new(items, cx).with_value("move", cx));
cx.subscribe(&control, |control, event: &DockSelected, cx| {
    control.update(cx, |dock, cx| dock.set_value(Some(event.0.clone()), cx));
}).detach();

use gpui::prelude::*;
use kui::components::liquid_tab_bar::{
    LiquidTabBar, LiquidTabChanged, LiquidTabIcon, LiquidTabItem, liquid_panel_id,
};

let control = cx.new(|cx| {
    LiquidTabBar::new(
        vec![
            LiquidTabItem::new("home", "Home", LiquidTabIcon::Home),
            LiquidTabItem::new("saved", "Saved", LiquidTabIcon::Bookmark),
            LiquidTabItem::new("inbox", "Inbox", LiquidTabIcon::Inbox)
                .with_badge(2)
                .with_badge_label("2 unread"),
        ],
        "home",
        cx,
    )
    .with_id("main-sections")
});
cx.subscribe(&control, |bar, event: &LiquidTabChanged, cx| {
    // Update the corresponding host panel as part of accepting the new section.
    bar.update(cx, |bar, cx| bar.set_value(event.0.clone(), cx));
}).detach();
let home_panel_id = liquid_panel_id("main-sections", "home");

use gpui::prelude::*;
use kui::components::orbit_menu::{OrbitAction, OrbitIcon, OrbitInvoked, OrbitMenu, OrbitTone};
use kui::primitives::glyph::Glyph;

let menu = cx.new(|cx| {
    OrbitMenu::new(
        vec![
            OrbitAction::new("pin", "Pin", Glyph::Pin).with_done("Pinned"),
            OrbitAction::new("share", "Share", OrbitIcon::Share),
            OrbitAction::new("remove", "Remove", Glyph::Trash).with_tone(OrbitTone::Danger),
        ],
        window,
        cx,
    )
    .with_label("Note actions")
});
cx.subscribe(&menu, |_, event: &OrbitInvoked, _| {
    // Dispatch event.0 to the host's action handler.
    let action = &event.0;
    debug_assert!(matches!(action.as_ref(), "pin" | "share" | "remove"));
}).detach();
